import { useEffect, useMemo, useRef, useState } from 'react';
import { JxButton, JxInputField, JxStepper } from '@jinx-ui/react';

export interface RegistrationValues {
  name: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  zip: string;
}

export interface RegistrationWizardProps {
  onSubmit: (values: RegistrationValues) => void;
}

const STEPS = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const EMPTY: RegistrationValues = { name: '', email: '', phone: '', city: '', street: '', zip: '' };

function validate(values: RegistrationValues, step: number): Partial<Record<keyof RegistrationValues, string>> {
  if (step === 0) {
    return {
      name: values.name.trim() ? undefined : 'Укажите имя',
      email: values.email.includes('@') ? undefined : 'Укажите адрес с символом @',
      phone: values.phone.replace(/\D/g, '').length >= 10 ? undefined : 'Укажите номер из 10 цифр',
    };
  }
  if (step === 1) {
    return {
      city: values.city.trim() ? undefined : 'Укажите город',
      street: values.street.trim() ? undefined : 'Укажите улицу и дом',
      zip: /^\d{6}$/.test(values.zip) ? undefined : 'Индекс из 6 цифр',
    };
  }
  return {};
}

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(EMPTY);
  const [showErrors, setShowErrors] = useState(false);
  const firstFieldRef = useRef<HTMLInputElement>(null);

  const errors = useMemo(() => validate(values, step), [values, step]);
  const hasErrors = Object.values(errors).some(Boolean);
  const isLast = step === STEPS.length - 1;

  useEffect(() => {
    firstFieldRef.current?.focus();
  }, [step]);

  const set = (key: keyof RegistrationValues) => (event: React.ChangeEvent<HTMLInputElement>) =>
    setValues((prev) => ({ ...prev, [key]: event.target.value }));

  const errorOf = (key: keyof RegistrationValues) => (showErrors ? errors[key] : undefined);

  const goNext = () => {
    if (hasErrors) {
      setShowErrors(true);
      firstFieldRef.current?.focus();
      return;
    }
    setShowErrors(false);
    setStep((prev) => Math.min(prev + 1, STEPS.length - 1));
  };

  const goBack = () => {
    setShowErrors(false);
    setStep((prev) => Math.max(prev - 1, 0));
  };

  const summary: Array<[string, string]> = [
    ['Имя', values.name],
    ['Почта', values.email],
    ['Телефон', values.phone],
    ['Город', values.city],
    ['Улица и дом', values.street],
    ['Индекс', values.zip],
  ];

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        if (isLast) onSubmit(values);
        else goNext();
      }}
      style={{ display: 'flex', flexDirection: 'column', gap: '24px', maxWidth: '520px' }}
    >
      <JxStepper steps={STEPS} current={step} />

      <div style={{ display: 'grid', gap: '12px' }}>
        {step === 0 && (
          <>
            <JxInputField
              ref={firstFieldRef}
              label="Имя и фамилия"
              required
              autoComplete="name"
              value={values.name}
              onChange={set('name')}
              errorText={errorOf('name')}
            />
            <JxInputField
              label="Электронная почта"
              type="email"
              required
              autoComplete="email"
              value={values.email}
              onChange={set('email')}
              errorText={errorOf('email')}
              helperText="Пришлём письмо для подтверждения"
            />
            <JxInputField
              label="Телефон"
              type="tel"
              required
              prefix="+7"
              autoComplete="tel"
              value={values.phone}
              onChange={set('phone')}
              errorText={errorOf('phone')}
            />
          </>
        )}

        {step === 1 && (
          <>
            <JxInputField
              ref={firstFieldRef}
              label="Город"
              required
              autoComplete="address-level2"
              value={values.city}
              onChange={set('city')}
              errorText={errorOf('city')}
            />
            <JxInputField
              label="Улица и дом"
              required
              autoComplete="street-address"
              value={values.street}
              onChange={set('street')}
              errorText={errorOf('street')}
            />
            <JxInputField
              label="Почтовый индекс"
              required
              inputMode="numeric"
              autoComplete="postal-code"
              value={values.zip}
              onChange={set('zip')}
              errorText={errorOf('zip')}
              helperText="Шесть цифр, например 190000"
            />
          </>
        )}

        {step === 2 && (
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: 'minmax(120px, auto) 1fr',
              gap: '8px 16px',
              margin: 0,
              padding: '16px',
              background: 'var(--jx-surface)',
              border: '1px solid var(--jx-border)',
              borderRadius: 'var(--jx-r)',
              color: 'var(--jx-text)',
              fontFamily: 'var(--jx-font-sans)',
            }}
          >
            {summary.map(([label, value]) => (
              <div key={label} style={{ display: 'contents' }}>
                <dt style={{ color: 'var(--jx-text-2)' }}>{label}</dt>
                <dd style={{ margin: 0, overflowWrap: 'anywhere' }}>{value || '—'}</dd>
              </div>
            ))}
          </dl>
        )}
      </div>

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        <JxButton variant="primary" type="submit">
          {isLast ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

